{
  "content": "import json, os, re, sys, time, traceback

ROOT = r"<run>"
sys.path.insert(0, os.path.join(ROOT, "work", "pylibs"))
os.environ.setdefault("NUMEXPR_MAX_THREADS", "8")

import torch
import dolphin
from dolphin import transcribe

PHR = os.path.join(ROOT, "work", "phrase")
OUT = os.path.join(ROOT, "work", "asr_dolphin_phrase.json")
MODEL_DIR = os.path.join(ROOT, "work", "models", "dolphin_small_cn")

_SPECIAL = re.compile(r"<\|[^<>|]*\|>")


def visible(s):
    return _SPECIAL.sub("[tok]", str(s)).strip()


FAM_OF = {}
for s in json.load(open(os.path.join(ROOT, "input", "segments.json"), encoding="utf-8"))["segments"]:
    FAM_OF[s["segment_id"]] = s["dialect"].split("/")[0]

REGION = {"吴语": ("zh", "WENZHOU"), "闽南语": ("zh", "MINNAN"), "客家话": ("zh", "CN"),
          "赣语": ("zh", "CN"), "湘语": ("zh", "HUNAN"), "粤语": ("ct", "GZ")}

torch.set_num_threads(8)
model = dolphin.load_model("small.cn", model_dir=MODEL_DIR, device="cpu")
print("loaded", flush=True)

results = {}
if os.path.exists(OUT):
    results = json.load(open(OUT, encoding="utf-8"))

files = sorted(f for f in os.listdir(PHR) if f.endswith(".wav"))
for i, f in enumerate(files, 1):
    key = f[:-4]
    if key in results:
        continue
    sid = key.split("_")[0]
    lg, reg = REGION[FAM_OF[sid]]
    try:
        r = transcribe(model, os.path.join(PHR, f), lang_sym=lg, region_sym=reg, word_timestamp=True)
        g = (lambda k, d=None: r.get(k, d) if isinstance(r, dict) else getattr(r, k, d))
        txt = visible(g("text_nospecial") or g("text") or "")
        raw_w = g("word_timestamps") or []
        wts = []
        for w in raw_w:
            gw = (lambda k, d=None: w.get(k, d) if isinstance(w, dict) else getattr(w, k, d))
            wts.append([visible(gw("text", "")), round(float(gw("start", 0) or 0), 3),
                        round(float(gw("end", 0) or 0), 3)])
        results[key] = {"text": txt, "words": wts}
    except Exception as e:
        results[key] = {"error": visible(str(e))[:200]}
        traceback.print_exc()
    if i % 8 == 0 or i == len(files):
        json.dump(results, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        print(f"{i}/{len(files)}", flush=True)

json.dump(results, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("ALL DONE", flush=True)
",
